package fetvisuals.modules.visuals;
import fetvisuals.module.*; import fetvisuals.render.RenderUtils; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext;
public final class DynamicCrosshair extends fetvisuals.module.Module {public DynamicCrosshair(){super("DynamicCrosshair","Movement-aware crosshair",Category.VISUALS);}public void onHud(DrawContext c,float d){MinecraftClient mc=MinecraftClient.getInstance();if(mc.player==null)return;double speed=Math.hypot(mc.player.getVelocity().x,mc.player.getVelocity().z);int gap=(int)Math.min(12,3+speed*20);int cx=mc.getWindow().getScaledWidth()/2,cy=mc.getWindow().getScaledHeight()/2;RenderUtils.rect(c,cx-1,cy-gap-5,2,5,0xFFD7C0FF);RenderUtils.rect(c,cx-1,cy+gap,2,5,0xFFD7C0FF);RenderUtils.rect(c,cx-gap-5,cy-1,5,2,0xFFD7C0FF);RenderUtils.rect(c,cx+gap,cy-1,5,2,0xFFD7C0FF);}}
